css:
.card {
  width: 240px;
  height: 354px;
  position: relative;
  border-radius: 16px;
  overflow: hidden;
  cursor: pointer;
  animation: name-of-animation 2s;
}

.card-img {
  position: absolute;
  height: 100%;
  width: 100%;
  background: linear-gradient(144deg,#af40ff,#5b42f3 50%,#00ddeb);
}

.card-info {
  position: absolute;
  width: 100%;
  bottom: 0;
  padding: 1.7rem;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
}

.card-icon {
  opacity: 0;
  transform: translateX(-20%);
  width: 2em;
  height: 2em;
  transition: all .3s ease-in-out;
  position: relative;
  left: -0.1em;
  top: -3px;
}

.icon {
  --size: 28px;
  width: var(--size);
  height: var(--size);
  filter: invert(1);
  margin-top: 1px;
  margin-left: -5px;
}

.card-text p {
  line-height: 140%;
  white-space: nowrap;
}

.text-title {
  font-weight: 700;
  font-size: 2.1rem;
  color: rgb(255, 255, 255);
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
}

.text-subtitle {
  color: rgb(255, 255, 255);
  font-weight: 500;
  font-size: 1.2rem;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
}

.card:hover .card-icon {
  opacity: 1;
  transform: translateX(20%);
}

@keyframes name-of-animation {
  0% {
    opacity: 0;
  }

  100% {
    opacity: 1;
  }
}
